use vstd::prelude::*;

verus! {

fn less(a: Vec<i8>, b: Vec<i8>) -> (out: Vec<bool>)
    requires
        a.len() == b.len(),
    ensures
        out.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> (out[i] <==> a[i] < b[i]),
{
    let n = a.len();
    let mut out: Vec<bool> = Vec::new();

    let mut i: usize = 0;
    while i < n
        invariant
            a.len() == b.len(),
            n == a.len(),
            i <= n,
            out.len() == i,
            forall|j: int| 0 <= j < i ==> (out[j] <==> a[j] < b[j]),
        decreases n - i,
    {
        // Read current elements, compute comparison, push to output
        let ai = a[i];
        let bi = b[i];
        let r: bool = ai < bi;

        out.push(r);

        i = i + 1;
    }

    out
}

} // verus!

